/**
 * Seeded pseudo-random sampling for Thompson selection.
 *
 * A deterministic uniform generator (mulberry32) plus normal, gamma, Beta, and exponential samplers.
 * Seeding makes routing reproducible: the same seed and the same posteriors always pick the same
 * model, which matters for testable, auditable decisions. Pure, dependency-free.
 *
 * @packageDocumentation
 */
/** A uniform random source returning a float in [0, 1). */
type Rng = () => number;
/** Create a deterministic uniform generator from a 32-bit seed (mulberry32). */
declare function mulberry32(seed: number): Rng;

export { type Rng as R, mulberry32 as m };
